    return to_kg(parse_number(text, thousands, decimal), unit)


def first_token_unit(value):
    token = value.strip().split()[0].lower() if value.strip() else ""
    return token if token in FACTORS else None


def split_records(text, delim):
    lines = text.split("\n")
    buffer = None
    for line in lines:
        line = line.rstrip("\r") if buffer is None else line
        if buffer is None:
            if not line.strip():
                continue
            if line.startswith("#"):
                yield ("comment", line)
                continue
            buffer = line
        else:
            buffer += "\n" + line
        if delim != "," or buffer.count('"') % 2 == 0:
            yield ("row", buffer)
            buffer = None
    if buffer is not None:
        yield ("row", buffer)


def parse_delimited(depot, text):
    delim = DELIMS[depot]
    columns = COLUMNS[depot]
    seq = None
    directives = {}
    header = None
    records = []
    for kind, content in split_records(text, delim):
        if kind == "comment":
            match = re.match(r"^#\s*([^:=]+?)\s*:\s*(.*)$", content)
            if match:
                directives[re.sub(r"\s+", " ", match.group(1).lower())] = match.group(2).strip()
                if match.group(1).strip().lower() == "seq":
                    seq = int(match.group(2))
            else:
                found = re.search(r"\bseq=(\d+)", content)
                if found:
                    seq = int(found.group(1))
            continue
        if delim == ",":
            fields = next(csv.reader([content], delimiter=",", quotechar='"'))
        else:
            fields = content.split(delim)
        lowered = [field.strip().lower() for field in fields]
        if lowered and all(name in columns for name in lowered):
            header = lowered
            continue
        if header is None:
            continue
        record = build_delimited(depot, header, fields, directives)
        if record is not None:
            records.append(record)
    return seq, records


def build_delimited(depot, header, fields, directives):
    date_form = (directives.get("dates") or directives.get("date format")
                 or directives.get("date") or BASE_DATE[depot])
    unit = BASE_UNIT[depot]
    for name in ("unit", "weight unit"):
        if name in directives:
            unit = first_token_unit(directives[name]) or unit
    thousands, decimal = "", "."
    if depot == "east":
        thousands = ","
        weight_col = "gross"
        if len(fields) == len(header) + 1:
            index = header.index("gross")
            candidate = fields[index + 1].strip().lower()
            if candidate in FACTORS:
                unit = candidate
                fields = fields[:index + 1] + fields[index + 2:]
    elif depot == "west":
        thousands, decimal = ".", ","
        weight_col = "weight"
    elif depot == "lakeside":
        weight_col = "gross_kg"
    else:
        weight_col = "weight"
    if len(fields) != len(header):
        if depot == "east" and fields and fields[0].strip().upper() == "TOTAL":
            return None
        return None
    row = dict(zip(header, [field.strip() for field in fields]))
    if depot == "east" and row.get("id", "").upper() == "TOTAL":
        return None
    if depot == "harbor":
        number = id_number(row["ref"])
    elif depot == "river":
        number = id_number(row["ref"])
    else:
        number = id_number(row["id"])
    if number is None:
        return None
    kind = TYPE_MAP[row.get({"east": "type", "harbor": "rec", "lakeside": "kind",
                             "river": "t", "west": "typ"}[depot], "").lower()]
    if kind == "void":
        return {"number": number, "kind": kind}
    suffix = re.search(r"_(kg|g|lb|oz)$", weight_col)
    if suffix:
        unit = suffix.group(1)
    kg = weight_value(row[weight_col], unit, thousands, decimal)
    status_raw = row.get("state") if depot == "harbor" else row.get("status")
    status = HARBOR_STATUS.get((status_raw or "").upper()) if depot == "harbor" else norm_status(status_raw)
    ship_col = "date" if depot == "harbor" else "shipped"
    shipped = parse_date(row[ship_col], date_form)
    return {"number": number, "kind": kind, "kg": kg, "status": status, "date": shipped}


def parse_north(text):
    seq = None
    records = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        value = json.loads(line)
        items = value if isinstance(value, list) else [value]
        for item in items:
            if not isinstance(item, dict):
                continue
            if "meta" in item and "id" not in item:
                if "seq" in item["meta"]:
                    seq = int(item["meta"]["seq"])
                continue
            number = id_number(str(item.get("id", "")))
            if number is None:
                continue
            kind = TYPE_MAP[str(item.get("kind", "new")).lower()]
            if kind == "void":
                records.append({"number": number, "kind": kind})
                continue
            kg = None
            for key, raw in item.items():
                match = re.fullmatch(r"weight_(kg|g|lb|oz)", key)
                if match:
                    kg = to_kg(str(raw), match.group(1))
            stamp = parse_datetime(item["shipped_at"]) if "T" in item["shipped_at"] else None
            shipped = stamp.date() if stamp else parse_date(item["shipped_at"], "iso")
            records.append({"number": number, "kind": kind, "kg": kg,
                            "status": norm_status(item.get("status")), "date": shipped})
    return seq, records


def parse_central(data):
    root = ET.fromstring(data)
    seq = int(root.get("seq")) if root.get("seq") else None
    base_unit = (root.get("weight-unit") or "kg").lower()
    records = []
    for element in root.iter("shipment"):
        number = id_number(element.get("id"))
        if number is None:
            continue
        kind = TYPE_MAP[(element.get("type") or "new").lower()]
        if kind == "void":
            records.append({"number": number, "kind": kind})
            continue
        weight = element.find("weight")
        unit = (weight.get("unit") or base_unit).lower()
        kg = to_kg(weight.text.strip().replace(",", ""), unit)
        child = element.find("shipped")
        raw = child.text.strip() if child is not None else element.get("shipped")
        if re.match(r"^\d{4}-\d{2}-\d{2}", raw):
            shipped = parse_datetime(raw).date() if "T" in raw else date.fromisoformat(raw)
        else:
            shipped = parse_named(raw)
        status = norm_status(element.findtext("status"))
        records.append({"number": number, "kind": kind, "kg": kg, "status": status, "date": shipped})
    return seq, records


def load_layouts():
    return {
        "FW1": (42, [("id", 0, 9), ("type", 9, 10), ("shipped", 10, 17), ("weight", 17, 25), ("status", 25, 26)],
                "yyyyddd", Decimal("0.001")),
        "FW2": (43, [("type", 0, 1), ("id", 1, 10), ("shipped", 10, 18), ("weight", 18, 26), ("status", 26, 27)],
                "yyyymmdd", Decimal("0.01")),
        "FW3": (41, [("id", 0, 9), ("shipped", 9, 16), ("type", 16, 17), ("weight", 17, 24), ("status", 24, 25)],
                "yyyyddd", FACTORS["lb"] / 10),
    }


def parse_south(text):
    layouts = load_layouts()
    by_length = {spec[0]: name for name, spec in layouts.items()}
    seq = None
    current = None
    records = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if "\x0c" in line or "SHIPMENT LISTING" in line:
            continue
        if line.startswith("#"):
            match = re.match(r"^#LAYOUT\s+(\S+)", line)
            if match:
                current = match.group(1)
            match = re.match(r"^#SEQ\s+(\d+)", line)
            if match:
                seq = int(match.group(1))
            continue
        if len(line) in by_length:
            name = by_length[len(line)]
        elif current:
            name = current
            line = line.ljust(layouts[name][0])
        else:
            continue
        length, fields, date_form, factor = layouts[name]
        row = {key: line[start:end] for key, start, end in fields}
        number = id_number(row["id"])
        kind = TYPE_MAP[row["type"].strip().lower()]
        if kind == "void":
            records.append({"number": number, "kind": kind})
            continue
        kg = Decimal(int(row["weight"])) * factor
        shipped = parse_date(row["shipped"].strip(), date_form)
        status = FW_STATUS.get(row["status"].strip().upper())
        records.append({"number": number, "kind": kind, "kg": kg, "status": status, "date": shipped})
    return seq, records


def load_export(depot, path):
    data = read_bytes(path)
    if depot == "central":
        return parse_central(data)
    text = decode(data)
    if depot == "north":
        return parse_north(text)
    if depot == "south":
        return parse_south(text)
    return parse_delimited(depot, text)


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-")[0].lower()
        seq, records = load_export(depot, path)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, records))

    corrections = 0
    resends = 0
    current = {}
    for depot, items in exports.items():
        items.sort(key=lambda item: (item[0], item[1]))
        state = {}
        for _, _, records in items:
            for record in records:
                number = record["number"]
                if record["kind"] == "new":
                    if number in state:
                        resends += 1
                    else:
                        state[number] = record
                elif record["kind"] == "correction":
                    state[number] = record
                    corrections += 1
                else:
                    state.pop(number, None)
                    corrections += 1
        current[depot] = state

    def rank(depot):
        return HANDOVER_ORDER.index(depot) if depot in HANDOVER_ORDER else len(HANDOVER_ORDER)

    owners = {}
    for depot in sorted(current, key=rank):
        for number, record in current[depot].items():
            owners.setdefault(number, []).append((depot, record))

    depots = {depot: [0, Decimal(0)] for depot in exports}
    months = {}
    handovers = 0
    for number, entries in owners.items():
        if len(entries) > 1:
            handovers += 1
        depot, record = entries[0]
        if record["status"] not in ("delivered", "delivered_late"):
            continue
        depots[depot][0] += 1
        depots[depot][1] += record["kg"]
        key = "%04d-%02d" % (record["date"].year, record["date"].month)
        bucket = months.setdefault(key, [0, Decimal(0)])
        bucket[0] += 1
        bucket[1] += record["kg"]

    def pack(bucket):
        total = bucket[1].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return {"shipments": bucket[0], "total_kg": float(total)}

    result = {
        "depots": {depot: pack(depots[depot]) for depot in sorted(depots)},
        "months": {key: pack(months[key]) for key in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as handle:
        json.dump(result, handle, indent=2)
        handle.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
